-- ROOFING/EXTERIORS - Inspection Report
--
-- Property header (with two inline ballot-box Yes/No-style fields for
-- building/roof type, same technique as the CLEANING checklist template's
-- SDS Binder field, since they need to sit inline in a single table cell),
-- an OSHA §1926 Sub-part M safety checklist plus a 2-photo "Safety setup &
-- ladder tie-off" row, a condition-survey table, a "Measurements & Test
-- Cuts (if taken)" table, a flashings & penetrations table pre-seeded with
-- four common details (step flashing, chimney cricket, pipe boots,
-- counter-flashing), a narrative summary prompt, a Snippets terms
-- placeholder ("[INSERT SNIPPET]"), and an inspector/owner sign-off. No
-- merge tokens -- every field is hand-filled per inspection, matching the
-- rest of the working-document family.
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-roofing-inspection-report',
  NULL,
  NULL,
  'ROOFING/EXTERIORS - Inspection Report',
  jsonb_build_object(
    'style', 'report',
    'description', 'Property header, safety checklist, condition survey, test cuts, flashings & penetrations, and inspector sign-off.',
    'html', $html$<h1>ROOFING/EXTERIORS - Inspection Report</h1><h2>Property Header</h2><table><tbody><tr><th><p>Field</p></th><th><p>Value</p></th></tr><tr><td><p>Project / Address</p></td><td><p></p></td></tr><tr><td><p>Building Type</p></td><td><p>&#9744; Residential &#9744; Commercial</p></td></tr><tr><td><p>Roof Type</p></td><td><p>&#9744; Steep-Slope &#9744; Low-Slope</p></td></tr><tr><td><p>Inspection Date</p></td><td><p></p></td></tr><tr><td><p>Inspector / Cert. #</p></td><td><p></p></td></tr><tr><td><p>Weather (Temp &deg;F / Wind mph / RH %)</p></td><td><p></p></td></tr></tbody></table><hr><h2>Safety Checklist (OSHA &sect;1926 Sub-part M)</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Fall-protection (PFAS, guardrails, or safety monitor) in place</p></li><li data-type="taskItem" data-checked="false"><p>Ladder secured &amp; extends &ge;3 ft above eave</p></li><li data-type="taskItem" data-checked="false"><p>Roof dry / no ice or lightning risk</p></li><li data-type="taskItem" data-checked="false"><p>PPE (hard-hat, high-vis, boots) worn</p></li></ul><p>Safety setup &amp; ladder tie-off</p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%201%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%202%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 2"></p><hr><h2>Condition Survey &ndash; Section / Plane</h2><table><tbody><tr><th><p>Section / Plane</p></th><th><p>Material</p></th><th><p>Age (yrs)</p></th><th><p>Condition (1 Good &ndash; 5 Fail)</p></th><th><p>Defects (Blow-off, Hail, Nail Pop, Ponding)</p></th><th><p>Code Ref.</p></th><th><p>📷 Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Measurements &amp; Test Cuts <em>(if taken)</em></h2><table><tbody><tr><th><p>Location</p></th><th><p>Core Cut Depth (in.)</p></th><th><p>Layers</p></th><th><p>Insulation R-Value</p></th><th><p>Moisture (Y/N)</p></th><th><p>📷 Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Flashings &amp; Penetrations</h2><table><tbody><tr><th><p>Detail</p></th><th><p>Status (OK / Repair / Replace)</p></th><th><p>Notes</p></th><th><p>📷 Photo</p></th></tr><tr><td><p>Step flashing</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Chimney cricket</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Pipe boots</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Counter-flashing</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Summary &amp; Recommendations</h2><p><em>Provide narrative on overall roof health, estimated remaining life, code upgrades (e.g., IRC R905.2.7 ice-barrier), and next-step actions (repair vs. full replacement).</em></p><hr><p><strong><u>Standard Terms &amp; Conditions</u></strong> <span style="color: rgb(59,130,246)">[INSERT SNIPPET]</span></p><p><em>Inspection performed per ASTM E108 visual &amp; ASTM D7158 uplift guidelines. Findings are visual only; concealed damage may exist.</em></p><hr><h2>Sign-off</h2><table><tbody><tr><th><p>Role</p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p>Inspector</p></td><td><p></p></td><td><p></p></td><td><p>✍️</p></td></tr><tr><td><p>Owner / Rep</p></td><td><p></p></td><td><p></p></td><td><p>✍️</p></td></tr></tbody></table>$html$
  ),
  ARRAY[]::text[]
)
ON CONFLICT (slug) DO UPDATE
